import { MyPaymentQRcode } from '~/entities/qr-code/model/types';
import { calculateCRC16 } from './crc';

type Encoding = 'an' | 'n' | 'b' | 'hex' | 'utf8';

export const CPM_FIXED_DEFS = {
  PAYLOAD_FORMAT_INDICATOR: {
    tag: '85',
    value: 'CPV01',
    encoding: 'an',
  },
  APP_TEMPLATE: {
    tag: '61',
    children: [
      //{ tag: '4F', value: 'A000000CBDC01', encoding: 'b' }, // 확정되지 않음
      { tag: '50', value: 'CBDC WON', encoding: 'an' }, // Application Label
      //{ tag: '5A', value: '00000000' } // Application Primary Account Number (PAN)
    ],
    encoding: 'b', // Binary (BER-TLV)
  },
  APPLICATION_TEMPLATE: {
    tag: '63',
    children: [
      //{ tag: '9F08', value: '10', encoding: 'b' }, // Application Version Number
      //{ tag: '9F01', value: '00' }, // Transaction Code(AKA, TxCode) => 변동
      //{ tag: '9F02', value: '000000000000' }, // Payer Bank Code => 변동
      //{ tag: '9F03', value: '000000000000' }, // Voucher Id => 변동
    ],
    encoding: 'b', // Binary (BER-TLV)
  },
} as const;

type CpmCtx = {
  txCode?: string; // 9F01
  customerBankCode?: string; // 9F02
  vouchId?: string; // 9F03
};

type TLVItem = { tag: string; value: string; encoding?: Encoding } | { tag: string; children: TLVItem[] };
type GeneratorOptions = {
  autoCrc?: boolean;
  crcTag?: string; // 보통 "63" (MPM CRC), 네 스펙에 맞게 바꿔도 됨
};

function pushIf<T>(arr: T[], cond: any, item: T) {
  if (cond) arr.push(item);
}

export function buildCpmSpec(ctx: MyPaymentQRcode): TLVItem[] {
  // 61(APP_TEMPLATE) children 구성
  const appChildren: TLVItem[] = [...CPM_FIXED_DEFS.APP_TEMPLATE.children];

  // 63(APPLICATION_TEMPLATE) children 구성
  const applicationChildren: TLVItem[] = [...CPM_FIXED_DEFS.APPLICATION_TEMPLATE.children];

  pushIf(applicationChildren, ctx.txCode, { tag: '9F01', value: ctx.txCode!, encoding: 'an' });
  pushIf(applicationChildren, ctx.customerBankCode, { tag: '9F02', value: ctx.customerBankCode!, encoding: 'an' });
  pushIf(applicationChildren, ctx.vouchId, { tag: '9F03', value: ctx.vouchId!, encoding: 'an' });

  // 최종 TLV 트리
  const spec: TLVItem[] = [
    CPM_FIXED_DEFS.PAYLOAD_FORMAT_INDICATOR as any,

    { tag: CPM_FIXED_DEFS.APP_TEMPLATE.tag, children: appChildren },
    { tag: CPM_FIXED_DEFS.APPLICATION_TEMPLATE.tag, children: applicationChildren },
  ];

  //console.log('빌드된 CPM 스펙 >>>> ', JSON.stringify(spec, null, 2));
  return spec;
}

/** ====== 인코더들 ====== */
function encodeAsciiStrict(s: string): Uint8Array {
  const out = new Uint8Array(s.length);
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c > 0x7f) throw new Error(`Non-ASCII char at ${i}: "${s[i]}"`);
    out[i] = c;
  }
  return out;
}

function encodeHex(hex: string): Uint8Array {
  let clean = hex.replace(/\s+/g, '').toUpperCase();

  // 홀수면 앞에 0 패딩
  if (clean.length % 2 === 1) clean = '0' + clean;

  // hex 검증
  if (!/^[0-9A-F]*$/.test(clean)) {
    const bad = clean.match(/[^0-9A-F]/)?.[0];
    throw new Error(`Invalid hex: contains "${bad}" in "${hex}"`);
  }

  const out = new Uint8Array(clean.length / 2);
  for (let i = 0; i < out.length; i++) {
    out[i] = Number.parseInt(clean.slice(i * 2, i * 2 + 2), 16);
  }
  return out;
}

function encodeValue(value: string, encoding: Encoding = 'an'): Uint8Array {
  if (encoding === 'an') return encodeAsciiStrict(value);
  if (encoding === 'utf8') return new TextEncoder().encode(value);
  if (encoding === 'hex' || encoding === 'b') return encodeHex(value);
  throw new Error(`Unsupported encoding: ${encoding}`);
}

function bytesToHexNoSpace(bytes: Uint8Array): string {
  let hex = '';
  for (let i = 0; i < bytes.length; i++) {
    hex += bytes[i].toString(16).padStart(2, '0');
  }
  return hex.toUpperCase();
}

function encodeBerLength(len: number): Uint8Array {
  if (len <= 0x7f) return Uint8Array.of(len);
  if (len <= 0xff) return Uint8Array.of(0x81, len);
  if (len <= 0xffff) return Uint8Array.of(0x82, (len >> 8) & 0xff, len & 0xff);
  throw new Error(`Length too large: ${len}`);
}

export function buildRawHexFromSpec(items: TLVItem[]): string {
  let rawHex = '';

  for (const item of items) {
    const tagHex = item.tag.toUpperCase(); // 그대로 사용

    let valueBytes: Uint8Array;
    if ('value' in item) {
      valueBytes = encodeValue(item.value, item.encoding);
    } else {
      const childrenHex = buildRawHexFromSpec(item.children);
      valueBytes = encodeHex(childrenHex);
    }

    const lenHex = bytesToHexNoSpace(encodeBerLength(valueBytes.length));
    const valueHex = bytesToHexNoSpace(valueBytes);

    rawHex += tagHex + lenHex + valueHex;
  }

  return rawHex;
}

function hexToBase64(hex: string): string {
  const bytes = encodeHex(hex);

  // Node
  if (typeof Buffer !== 'undefined') {
    return Buffer.from(bytes).toString('base64');
  }

  // Browser
  let binary = '';
  const chunkSize = 0x8000;
  for (let i = 0; i < bytes.length; i += chunkSize) {
    binary += String.fromCharCode(...bytes.subarray(i, i + chunkSize));
  }
  return btoa(binary);
}

/**
 * 최종: spec → rawHex(+CRC 옵션) → base64
 */
export function generateBase64FromSpec(
  spec: TLVItem[],
  options: GeneratorOptions = { autoCrc: true, crcTag: '63' },
): string {
  const { autoCrc = true, crcTag = '63' } = options;

  // 1) rawHex 생성
  let rawHex = buildRawHexFromSpec(autoCrc ? spec.filter((t) => t.tag !== crcTag) : spec);

  // 2) CRC
  if (autoCrc) {
    const hexForCrc = rawHex + `${crcTag}04`;
    const crc = calculateCRC16(encodeHex(hexForCrc));
    rawHex = hexForCrc + crc;
  }

  // 3) 최종 hex → base64
  return hexToBase64(rawHex);
}
