import { useQuery, useQueryClient } from '@tanstack/react-query';
import { GenerateTxCodeRequestDTO } from '~/entities/payment/api/dtos/types';
import { paymentApi } from '~/entities/payment/api/payment-api';
import { queries } from '~/shared/api/query-keys';

export const useTxCode = () => {
  const queryClient = useQueryClient();

  return useQuery({
    queryKey: queries.payment.generateTxCode.queryKey,
    queryFn: async () => {
      const latestKey = queryClient.getQueryData(queries.payment.generateTxCode.queryKey);
      if (!latestKey) {
        return null;
      }
      return paymentApi.generateTxCode(latestKey as GenerateTxCodeRequestDTO);
    },
    gcTime: 0,
  });
};
