import { isEmpty } from 'lodash-es';
import { QRCodeCanvas } from 'qrcode.react';
import { memo, useCallback, useEffect, useMemo, useState } from 'react';
import { Fragment } from 'react/jsx-runtime';
import { useGenerateTxCodeWithPinAuth } from '~/entities/payment/api/hooks/use-generate-tx-code-with-pin-auth';
import { useTxCode } from '~/entities/payment/api/hooks/use-tx-code';
import { usePaymentQRTimer } from '~/entities/payment/lib/use-payment-qr-timer';
import { buildCpmSpec, generateBase64FromSpec } from '~/entities/qr-code/lib/cpmFixedTags';
import { MyPaymentQRcode } from '~/entities/qr-code/model/types';
import { IS_DEV_PHASE } from '~/shared/config/environment';
import i18n from '~/shared/i18n/i18n';
import { RefreshButton } from '~/shared/ui/reset-button';

export const PaymentQRCode = memo(function PaymentQRCode() {
  const { data } = useTxCode();
  const txData = data?.tbPayMastr;

  const { remainingTimeText, refreshTimer, remainingTime } = usePaymentQRTimer();
  const { generateTxCodeWithPinAuth } = useGenerateTxCodeWithPinAuth();
  const [dataBytes, setDataBytes] = useState<string>('');

  const qrCode = useMemo<MyPaymentQRcode | null>(() => {
    if (!txData?.txCd) return null;
    return {
      prefix: 'CBDC',
      txCode: txData.txCd,
      customerBankCode: txData.fromInsttCd ?? '',
      vouchId: txData.vouchId,
    };
  }, [txData?.txCd, txData?.fromInsttCd, txData?.vouchId]);

  const handleRefreshTimer = useCallback(() => {
    if (!txData) return;
    generateTxCodeWithPinAuth({
      vouchId: txData.vouchId,
      vouchAmt: txData.vouchAmt?.toString() ?? '',
      vouchAddres: txData?.vouchAddres ?? '',
      vouchBankCode: txData?.vouchBankCode ?? '',
      insttWalletAdres: txData.insttWalletAdres ?? '',
      vouchTypeNm: txData.vouchTyNm ?? '',
      vouchNm: txData.vouchNm ?? '',
      vouchTyCd: txData.vouchTyCd ?? '',
    });
  }, [txData, generateTxCodeWithPinAuth]);

  useEffect(() => {
    if (!isEmpty(qrCode)) {
      const spec = buildCpmSpec(qrCode);
      const base64Payload = generateBase64FromSpec(spec, {
        autoCrc: false,
      });
      setDataBytes(base64Payload);
    }

    if (qrCode?.txCode) {
      refreshTimer();
    }
  }, [qrCode?.txCode, refreshTimer]);

  if (remainingTime <= 0) {
    return (
      <Fragment>
        <div className="refresh-code">
          <div className="refresh-code-area">
            <RefreshButton onClick={handleRefreshTimer}>{i18n.t('reissue')}</RefreshButton>
          </div>
        </div>
        <div className="timer exp">
          <p>{i18n.t('validation:verificationTimeExpired')}</p>
        </div>
      </Fragment>
    );
  }

  const qrSize = IS_DEV_PHASE ? 250 : 160;

  return (
    <Fragment>
      <div className="barcode-img"></div>
      <div className="qr-img" style={IS_DEV_PHASE ? { width: '100%' } : {}}>
        {qrCode?.txCode ? (
          <QRCodeCanvas value={dataBytes} size={qrSize} level={'M'} />
        ) : (
          // <QRCode
          //   key={JSON.stringify(qrCode)}
          //   size={qrSize}
          //   className="h-auto max-w-full"
          //   value={JSON.stringify(qrCode)}
          //   viewBox={`0 0 160 160`}
          // />
          <div className="h-[10rem] w-[10rem] bg-[var(--main-bg-color)]"></div>
        )}
      </div>
      <div className="timer">
        <p>
          {i18n.t('validTime')}
          <span> {remainingTimeText}</span>
        </p>
        <RefreshButton onClick={handleRefreshTimer} disabled={!qrCode?.txCode} />
      </div>
    </Fragment>
  );
});
