import { useLayoutEffect, useState } from 'react';
import { useLocation } from 'react-router-dom';
import { useSetHeaderTitle } from '~/widgets/sub-layout/use-sub-layout';
import { WebViewRedirectionBoundary } from '~/widgets/web-view/redirection-boundary';
import { useClearPayment } from '~/entities/payment/api/hooks/use-clear-payment';
import { PayShowTab } from '~/entities/payment/ui/pay-show-tab';
import { PaymentQRCode } from '~/entities/payment/ui/payment-qr-code';
import { PaymentSelectBottomSheet } from '~/entities/payment/ui/payment-select-bottom-sheet';
import { TokenInfoButton } from '~/entities/payment/ui/token-info-button';
import { TokenItem } from '~/entities/pin/api/dtos/types';
import { useSelectedVoucher } from '~/entities/voucher/api/hooks/use-selected-voucher';
import i18n from '~/shared/i18n/i18n';
import { useEffectOnceAfterPageRendered, useNavigate } from '~/shared/lib/hooks';
import { PATHS } from '~/shared/routes/paths';

type MyPaymentQRCodeLocationState = {
  tokenList?: TokenItem[];
};

export const MyPaymentQRCodePage = () => {
  const { navigate } = useNavigate();
  const { state } = useLocation();
  useSetHeaderTitle(i18n.t('qrPayment'));
  const { tokenList } = (state as MyPaymentQRCodeLocationState | null) ?? {};

  const [isOpenVoucherInfoBottomSheet, setIsOpenVoucherInfoBottomSheet] = useState(false);

  const { selectedVoucher } = useSelectedVoucher();
  const { clearPayment } = useClearPayment();

  const handleClickGuide = () => {
    navigate({ pathname: PATHS.paymentGuide, search: '?defaultTabIndex=1' });
  };

  const handleClickVoucherInfo = () => {
    setIsOpenVoucherInfoBottomSheet((prev) => !prev);
  };

  useLayoutEffect(() => {
    clearPayment();

    return () => {
      clearPayment();
    };
  }, []);

  useEffectOnceAfterPageRendered(() => {
    setIsOpenVoucherInfoBottomSheet(true);
  });

  return (
    <WebViewRedirectionBoundary>
      <div className="wrap bgw">
        <div className="content sub full-height">
          <div className="qr-pay-bg"></div>
          <div className="qr-pay-show">
            <PayShowTab />
            <div className="qr-img-area">
              <PaymentQRCode />
              <div className="pay-info-area">
                <TokenInfoButton tokenList={tokenList} />
                <button type="button" className="benefit-info" onClick={handleClickVoucherInfo}>
                  <p>{i18n.t('applyVoucherBenefits')}</p>
                  {selectedVoucher ? (
                    <p className="benefit-empty">{selectedVoucher.vouchNm}</p>
                  ) : (
                    <p className="benefit-empty">{i18n.t('noApply')}</p>
                  )}
                </button>
              </div>
            </div>
          </div>
          <div className="show-guide">
            <button type="button" onClick={handleClickGuide}>
              <span>&nbsp;</span>
              {i18n.t('usageGuide')}
            </button>
          </div>
        </div>
      </div>
      <PaymentSelectBottomSheet
        isOpen={isOpenVoucherInfoBottomSheet}
        onClose={() => setIsOpenVoucherInfoBottomSheet(false)}
      />
    </WebViewRedirectionBoundary>
  );
};
