import { addMilliseconds, format } from 'date-fns';
import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { DEFAULT_PAYMENT_TIME_OUT } from '~/entities/mobile-verification/model/constants';

const TIME_LIMIT = DEFAULT_PAYMENT_TIME_OUT;

export const usePaymentQRTimer = () => {
  const [remainingTime, setRemainingTime] = useState(TIME_LIMIT);
  const expirationTime = useMemo(() => {
    const date = new Date();
    return format(addMilliseconds(date, remainingTime), 'yyyy-MM-dd H:m:s');
  }, [remainingTime]);

  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null);

  const minutes = Math.floor(remainingTime / 1000 / 60);
  const seconds = Math.floor((remainingTime / 1000) % 60);

  const minutesDoubleDigit = minutes.toString().padStart(2, '0');
  const secondsDoubleDigit = seconds.toString().padStart(2, '0');
  const remainingTimeText = `${minutesDoubleDigit}:${secondsDoubleDigit}`;

  const startTimer = () => {
    timerRef.current = setInterval(() => {
      setRemainingTime((prev) => prev - 1000);
    }, 1000);
  };

  const refreshTimer = useCallback(() => {
    setRemainingTime((prevRemainingTime) => {
      if (timerRef.current !== null) clearInterval(timerRef.current);
      startTimer();
      return TIME_LIMIT;
    });
  }, []);

  const clearTimer = useCallback(() => {
    if (timerRef.current !== null) clearInterval(timerRef.current);
    setRemainingTime(TIME_LIMIT);
  }, []);

  useLayoutEffect(() => {
    clearTimer();
  }, []);

  useEffect(() => {
    return () => {
      if (timerRef.current !== null) clearInterval(timerRef.current);
    };
  }, []);

  useEffect(() => {
    if (remainingTime <= 0) {
      if (timerRef.current !== null) clearInterval(timerRef.current);
    }
  }, [remainingTime]);

  return { remainingTimeText, refreshTimer, expirationTime, remainingTime, clearTimer };
};
