import { useQuery, useQueryClient } from '@tanstack/react-query';
import { VoucherItemDTO } from '~/entities/voucher/api/dtos/voucher-item';
import { queries } from '~/shared/api/query-keys';

export const useSelectedVoucher = () => {
  const queryClient = useQueryClient();

  const { data: selectedVoucher } = useQuery({
    queryKey: queries.payment.selectedVoucher.queryKey,
    queryFn: () => {
      const data = queryClient.getQueryData<VoucherItemDTO>(queries.payment.selectedVoucher.queryKey);
      return data ?? null;
    },
    initialData: null,
    gcTime: 0,
  });

  const setSelectedVoucher = (voucher: VoucherItemDTO | null) => {
    queryClient.setQueryData(queries.payment.selectedVoucher.queryKey, voucher);
  };

  return { selectedVoucher, setSelectedVoucher };
};
